#!/usr/bin/env python3
import pandas as pd
import numpy as np
import json
import base64
import warnings
from io import BytesIO
warnings.filterwarnings('ignore')

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows")

# ── Type conversions ───────────────────────────────────────────────────────────
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')
df['MEAN_MOTION']  = pd.to_numeric(df['MEAN_MOTION'],  errors='coerce')
df['INCLINATION']  = pd.to_numeric(df['INCLINATION'],  errors='coerce')

# Extract launch year from OBJECT_ID (first 4 chars)
df['LAUNCH_YEAR'] = pd.to_numeric(df['OBJECT_ID'].str[:4], errors='coerce')

# ── Orbit classification ───────────────────────────────────────────────────────
def classify_orbit(row):
    mm  = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if mm > 14:
        return 'LEO'
    elif mm >= 11.25 and mm <= 14:
        # Could still be LEO; distinguish by eccentricity for HEO
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'LEO'
    elif mm >= 6 and mm < 11.25:
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'MEO'
    elif mm >= 0.8 and mm < 6:
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'GEO'  # includes sub-GEO MEO in this band
    else:
        return 'HEO'

# Simpler, standard thresholds:
# LEO: MEAN_MOTION > 11.25 (approx <2000 km)
# MEO: 1.5 < MEAN_MOTION <= 11.25
# GEO: 0.9 <= MEAN_MOTION <= 1.1  (and low eccentricity)
# HEO: high eccentricity regardless of mean motion

def classify_orbit_v2(row):
    mm  = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY'] if not pd.isna(row['ECCENTRICITY']) else 0
    if pd.isna(mm):
        return 'Unknown'
    # HEO first: high eccentricity signatures
    if ecc > 0.25:
        return 'HEO'
    if mm > 11.25:
        return 'LEO'
    elif mm > 2.0:
        return 'MEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1.1 and mm <= 2.0:
        return 'MEO'
    else:
        return 'HEO'  # very slow — highly eccentric or deep orbit

df['ORBIT_CLASS'] = df.apply(classify_orbit_v2, axis=1)

# ── Constellation identification ───────────────────────────────────────────────
CONSTELLATIONS = [
    ('STARLINK',    'STARLINK'),
    ('ONEWEB',      'ONEWEB'),
    ('IRIDIUM',     'IRIDIUM'),
    ('GPS',         'GPS'),
    ('GLOBALSTAR',  'GLOBALSTAR'),
    ('BEIDOU',      'BEIDOU'),
    ('GALILEO',     'GALILEO'),
    ('GLONASS',     'GLONASS'),
    ('ORBCOMM',     'ORBCOMM'),
    ('SPIRE',       'SPIRE'),
    ('PLANET',      'FLOCK'),
    ('SKYSAT',      'SKYSAT'),
]

def get_constellation(name):
    name_upper = str(name).upper()
    for label, prefix in CONSTELLATIONS:
        if name_upper.startswith(prefix):
            return label
    return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_constellation)

# ── KPIs ───────────────────────────────────────────────────────────────────────
total_sats      = len(df)
leo_count       = (df['ORBIT_CLASS'] == 'LEO').sum()
leo_share       = leo_count / total_sats * 100
starlink_count  = (df['CONSTELLATION'] == 'STARLINK').sum()
median_incl     = df['INCLINATION'].median()
post2020_count  = (df['LAUNCH_YEAR'] >= 2020).sum()

print(f"Total: {total_sats}, LEO: {leo_count} ({leo_share:.1f}%), Starlink: {starlink_count}")
print(f"Median inclination: {median_incl:.1f}°, Post-2020: {post2020_count}")

# ── Orbit regime breakdown ─────────────────────────────────────────────────────
orbit_counts = df['ORBIT_CLASS'].value_counts().reset_index()
orbit_counts.columns = ['Regime', 'Count']
orbit_counts['Share (%)'] = (orbit_counts['Count'] / total_sats * 100).round(1)

# ── Constellation breakdown ────────────────────────────────────────────────────
const_counts = df['CONSTELLATION'].value_counts().reset_index()
const_counts.columns = ['Constellation', 'Count']
const_counts['Share (%)'] = (const_counts['Count'] / total_sats * 100).round(1)

# ── Launch year trends ─────────────────────────────────────────────────────────
launch_by_year = df.groupby('LAUNCH_YEAR').size().reset_index(name='Count')
launch_by_year = launch_by_year[launch_by_year['LAUNCH_YEAR'] >= 1960].sort_values('LAUNCH_YEAR')
launch_by_year['Cumulative'] = launch_by_year['Count'].cumsum()

# ── Inclination distribution buckets ──────────────────────────────────────────
incl_bins  = [0, 10, 30, 60, 80, 90, 100, 180]
incl_labels = ['0–10°', '10–30°', '30–60°', '60–80°', '80–90°', '90–100°', '100–180°']
df['INCL_BIN'] = pd.cut(df['INCLINATION'], bins=incl_bins, labels=incl_labels, right=False)
incl_dist = df['INCL_BIN'].value_counts().sort_index().reset_index()
incl_dist.columns = ['Range', 'Count']

# ── Generate SVG charts ────────────────────────────────────────────────────────
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch

PALETTE = {
    'primary':   '#1a3a5c',
    'accent1':   '#2196F3',
    'accent2':   '#FF6B35',
    'accent3':   '#4CAF50',
    'accent4':   '#9C27B0',
    'accent5':   '#FF9800',
    'bg':        '#F8FAFD',
    'text':      '#1a2533',
    'grid':      '#e0e8f0',
    'leo':       '#2196F3',
    'meo':       '#4CAF50',
    'geo':       '#FF6B35',
    'heo':       '#9C27B0',
}

ORBIT_COLORS = {'LEO': PALETTE['leo'], 'MEO': PALETTE['meo'],
                'GEO': PALETTE['geo'], 'HEO': PALETTE['heo'], 'Unknown': '#aaa'}

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight',
                facecolor=fig.get_facecolor())
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

def style_ax(ax, title='', xlabel='', ylabel=''):
    ax.set_facecolor(PALETTE['bg'])
    ax.spines[['top','right']].set_visible(False)
    ax.spines[['left','bottom']].set_color(PALETTE['grid'])
    ax.tick_params(colors=PALETTE['text'], labelsize=9)
    ax.xaxis.label.set_color(PALETTE['text'])
    ax.yaxis.label.set_color(PALETTE['text'])
    ax.yaxis.grid(True, color=PALETTE['grid'], linewidth=0.7, zorder=0)
    ax.set_axisbelow(True)
    if title:  ax.set_title(title, fontsize=11, fontweight='bold', color=PALETTE['primary'], pad=10)
    if xlabel: ax.set_xlabel(xlabel, fontsize=9)
    if ylabel: ax.set_ylabel(ylabel, fontsize=9)

# ── Chart 1: Launch trend (bar + cumulative line) ─────────────────────────────
fig, ax1 = plt.subplots(figsize=(12, 5))
fig.patch.set_facecolor(PALETTE['bg'])

years = launch_by_year['LAUNCH_YEAR'].values
counts = launch_by_year['Count'].values
cumul  = launch_by_year['Cumulative'].values

colors = [PALETTE['accent2'] if y >= 2020 else PALETTE['accent1'] for y in years]
bars = ax1.bar(years, counts, color=colors, alpha=0.85, zorder=3, width=0.7)

ax2 = ax1.twinx()
ax2.plot(years, cumul, color=PALETTE['primary'], linewidth=2.5, zorder=4, marker='o',
         markersize=3, label='Cumulative')
ax2.set_facecolor(PALETTE['bg'])
ax2.spines[['top']].set_visible(False)
ax2.spines[['right']].set_color(PALETTE['grid'])
ax2.tick_params(colors=PALETTE['text'], labelsize=9)
ax2.set_ylabel('Cumulative Active Satellites', fontsize=9, color=PALETTE['primary'])
ax2.yaxis.label.set_color(PALETTE['primary'])

style_ax(ax1, title='Active Satellites by Launch Year',
         xlabel='Launch Year', ylabel='Satellites Launched (still active)')

# Annotation for 2020+
post2020_mask = years >= 2020
if post2020_mask.any():
    ax1.axvline(x=2019.5, color=PALETTE['accent2'], linestyle='--', linewidth=1.2, alpha=0.7)
    ax1.text(2019.8, max(counts)*0.9, 'Post-2020\nAcceleration',
             color=PALETTE['accent2'], fontsize=8, fontweight='bold')

from matplotlib.patches import Patch
legend_elements = [
    Patch(facecolor=PALETTE['accent1'], label='Pre-2020 launches'),
    Patch(facecolor=PALETTE['accent2'], label='Post-2020 launches'),
    plt.Line2D([0],[0], color=PALETTE['primary'], linewidth=2, label='Cumulative total'),
]
ax1.legend(handles=legend_elements, loc='upper left', fontsize=8,
           framealpha=0.9, facecolor='white', edgecolor=PALETTE['grid'])

fig.tight_layout()
chart_launch = fig_to_b64(fig)

# ── Chart 2: Orbit regime donut ───────────────────────────────────────────────
fig, ax = plt.subplots(figsize=(7, 5))
fig.patch.set_facecolor(PALETTE['bg'])
ax.set_facecolor(PALETTE['bg'])

regimes = orbit_counts['Regime'].tolist()
ocounts = orbit_counts['Count'].tolist()
ocolors = [ORBIT_COLORS.get(r, '#aaa') for r in regimes]
wedges, texts, autotexts = ax.pie(
    ocounts, labels=None, autopct='%1.1f%%', startangle=90,
    colors=ocolors, pctdistance=0.75,
    wedgeprops=dict(width=0.5, edgecolor='white', linewidth=2)
)
for at in autotexts:
    at.set_fontsize(9)
    at.set_color('white')
    at.set_fontweight('bold')

ax.legend(wedges, [f"{r} ({c:,})" for r, c in zip(regimes, ocounts)],
          loc='lower center', bbox_to_anchor=(0.5, -0.08), ncol=2,
          fontsize=9, framealpha=0.9, facecolor='white', edgecolor=PALETTE['grid'])
ax.set_title('Orbital Regime Distribution', fontsize=11, fontweight='bold',
             color=PALETTE['primary'], pad=10)

# Center label
ax.text(0, 0, f'{total_sats:,}\nSatellites', ha='center', va='center',
        fontsize=11, fontweight='bold', color=PALETTE['primary'])

fig.tight_layout()
chart_orbit = fig_to_b64(fig)

# ── Chart 3: Constellation bar ────────────────────────────────────────────────
fig, ax = plt.subplots(figsize=(9, 5))
fig.patch.set_facecolor(PALETTE['bg'])

top_const = const_counts[const_counts['Constellation'] != 'Other'].head(10)
bar_colors = [PALETTE['accent2'] if c == 'STARLINK' else PALETTE['accent1']
              for c in top_const['Constellation']]
hbars = ax.barh(top_const['Constellation'][::-1], top_const['Count'][::-1],
                color=bar_colors[::-1], alpha=0.88, zorder=3)

for bar, val in zip(hbars, top_const['Count'][::-1]):
    ax.text(bar.get_width() + 30, bar.get_y() + bar.get_height()/2,
            f'{val:,}', va='center', fontsize=8.5, color=PALETTE['text'])

style_ax(ax, title='Top Satellite Constellations & Operators',
         xlabel='Number of Active Satellites')
ax.xaxis.grid(True, color=PALETTE['grid'], linewidth=0.7, zorder=0)
ax.yaxis.grid(False)
ax.set_axisbelow(True)
ax.set_xlim(0, top_const['Count'].max() * 1.15)

fig.tight_layout()
chart_const = fig_to_b64(fig)

# ── Chart 4: Inclination distribution ────────────────────────────────────────
fig, ax = plt.subplots(figsize=(9, 4.5))
fig.patch.set_facecolor(PALETTE['bg'])

ax.bar(incl_dist['Range'], incl_dist['Count'],
       color=PALETTE['accent1'], alpha=0.85, zorder=3, edgecolor='white', linewidth=0.5)

# Highlight polar & near-equatorial
highlight_ranges = {'80–90°': PALETTE['accent2'], '90–100°': PALETTE['accent4']}
for i, row in incl_dist.iterrows():
    if row['Range'] in highlight_ranges:
        ax.bar(row['Range'], row['Count'],
               color=highlight_ranges[row['Range']], alpha=0.85, zorder=4,
               edgecolor='white', linewidth=0.5)

style_ax(ax, title='Inclination Distribution of Active Satellites',
         xlabel='Inclination Range', ylabel='Number of Satellites')
ax.tick_params(axis='x', rotation=15)

from matplotlib.patches import Patch
legend_elements2 = [
    Patch(facecolor=PALETTE['accent1'], label='Other inclinations'),
    Patch(facecolor=PALETTE['accent2'], label='Near-polar (80–90°)'),
    Patch(facecolor=PALETTE['accent4'], label='Retrograde polar (90–100°)'),
]
ax.legend(handles=legend_elements2, fontsize=8, framealpha=0.9,
          facecolor='white', edgecolor=PALETTE['grid'])

fig.tight_layout()
chart_incl = fig_to_b64(fig)

# ── Chart 5: Mean motion distribution (histogram) ─────────────────────────────
fig, ax = plt.subplots(figsize=(9, 4.5))
fig.patch.set_facecolor(PALETTE['bg'])

mm_valid = df['MEAN_MOTION'].dropna()
ax.hist(mm_valid, bins=80, color=PALETTE['accent1'], alpha=0.80,
        edgecolor='white', linewidth=0.3, zorder=3)

# Regime boundaries
for xv, label, col in [(11.25, 'LEO threshold\n(11.25)', PALETTE['geo']),
                        (1.0,   'GEO ≈ 1.0', PALETTE['heo'])]:
    ax.axvline(x=xv, color=col, linestyle='--', linewidth=1.5, alpha=0.85)
    ax.text(xv+0.1, ax.get_ylim()[1]*0.8 if ax.get_ylim()[1] > 0 else 100,
            label, fontsize=7.5, color=col)

style_ax(ax, title='Mean Motion Distribution (Orbits per Day)',
         xlabel='Mean Motion (rev/day)', ylabel='Satellite Count')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{int(x):,}'))

fig.tight_layout()
chart_mm = fig_to_b64(fig)

# ── Chart 6: Eccentricity distribution ───────────────────────────────────────
fig, ax = plt.subplots(figsize=(9, 4))
fig.patch.set_facecolor(PALETTE['bg'])

ecc_valid = df['ECCENTRICITY'].dropna()
ecc_valid_clipped = ecc_valid[ecc_valid < 0.5]

ax.hist(ecc_valid_clipped, bins=60, color=PALETTE['accent3'], alpha=0.82,
        edgecolor='white', linewidth=0.3, zorder=3)
ax.axvline(x=0.25, color=PALETTE['accent2'], linestyle='--', linewidth=1.5,
           label='HEO threshold (e > 0.25)')
ax.legend(fontsize=8, framealpha=0.9, facecolor='white', edgecolor=PALETTE['grid'])

style_ax(ax, title='Eccentricity Distribution (e < 0.5 shown)',
         xlabel='Eccentricity', ylabel='Satellite Count')

fig.tight_layout()
chart_ecc = fig_to_b64(fig)

# ── Prepare table data ─────────────────────────────────────────────────────────
orbit_table_html = orbit_counts.to_html(index=False, classes='data-table', border=0,
                                         float_format=lambda x: f'{x:.1f}')
const_table_html = const_counts.head(15).to_html(index=False, classes='data-table', border=0,
                                                    float_format=lambda x: f'{x:.1f}')
launch_table_html = launch_by_year.tail(15).to_html(index=False, classes='data-table', border=0)
incl_table_html = incl_dist.to_html(index=False, classes='data-table', border=0)

# ── Additional stats ───────────────────────────────────────────────────────────
mean_mm = df['MEAN_MOTION'].mean()
median_mm = df['MEAN_MOTION'].median()
mean_ecc = df['ECCENTRICITY'].mean()
pct_circular = (df['ECCENTRICITY'] < 0.01).sum() / len(df) * 100
starlink_share = starlink_count / total_sats * 100
non_starlink = total_sats - starlink_count
heo_count = (df['ORBIT_CLASS'] == 'HEO').sum()
meo_count = (df['ORBIT_CLASS'] == 'MEO').sum()
geo_count = (df['ORBIT_CLASS'] == 'GEO').sum()
leo_share_val = leo_count / total_sats * 100

epoch_min = df['EPOCH'].min()
epoch_max = df['EPOCH'].max()

# Launch decade breakdown
decade_map = {1960:'1960s',1970:'1970s',1980:'1980s',1990:'1990s',
              2000:'2000s',2010:'2010s',2020:'2020s'}
df['DECADE'] = (df['LAUNCH_YEAR'] // 10 * 10).map(decade_map)
decade_counts = df['DECADE'].value_counts().sort_index()

# ── Build HTML ─────────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<style>
  :root {{
    --primary:  #1a3a5c;
    --accent1:  #2196F3;
    --accent2:  #FF6B35;
    --accent3:  #4CAF50;
    --accent4:  #9C27B0;
    --bg:       #F8FAFD;
    --card-bg:  #ffffff;
    --border:   #dde6f0;
    --text:     #1a2533;
    --muted:    #5a6a7e;
