#!/usr/bin/env python3
import pandas as pd
import numpy as np
import json
import base64
import warnings
from io import BytesIO
warnings.filterwarnings('ignore')

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows")

# ── Type conversions ───────────────────────────────────────────────────────────
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')
df['MEAN_MOTION']  = pd.to_numeric(df['MEAN_MOTION'],  errors='coerce')
df['INCLINATION']  = pd.to_numeric(df['INCLINATION'],  errors='coerce')

# Extract launch year from OBJECT_ID (first 4 chars)
df['LAUNCH_YEAR'] = pd.to_numeric(df['OBJECT_ID'].str[:4], errors='coerce')

# ── Orbit classification ───────────────────────────────────────────────────────
def classify_orbit(row):
    mm  = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if mm > 14:
        return 'LEO'
    elif mm >= 11.25 and mm <= 14:
        # Could still be LEO; distinguish by eccentricity for HEO
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'LEO'
    elif mm >= 6 and mm < 11.25:
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'MEO'
    elif mm >= 0.8 and mm < 6:
        if not pd.isna(ecc) and ecc > 0.25:
            return 'HEO'
        return 'GEO'  # includes sub-GEO MEO in this band
    else:
        return 'HEO'

# Simpler, standard thresholds:
# LEO: MEAN_MOTION > 11.25 (approx <2000 km)
# MEO: 1.5 < MEAN_MOTION <= 11.25
# GEO: 0.9 <= MEAN_MOTION <= 1.1  (and low eccentricity)
# HEO: high eccentricity regardless of mean motion

def classify_orbit_v2(row):
    mm  = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY'] if not pd.isna(row['ECCENTRICITY']) else 0
    if pd.isna(mm):
        return 'Unknown'
    # HEO first: high eccentricity signatures
    if ecc > 0.25:
        return 'HEO'
    if mm > 11.25:
        return 'LEO'
    elif mm > 2.0:
        return 'MEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1.1 and mm <= 2.0:
        return 'MEO'
    else:
        return 'HEO'  # very slow — highly eccentric or deep orbit

df['ORBIT_CLASS'] = df.apply(classify_orbit_v2, axis=1)

# ── Constellation identification ───────────────────────────────────────────────
CONSTELLATIONS = [
    ('STARLINK',    'STARLINK'),
    ('ONEWEB',      'ONEWEB'),
    ('IRIDIUM',     'IRIDIUM'),
    ('GPS',         'GPS'),
    ('GLOBALSTAR',  'GLOBALSTAR'),
    ('BEIDOU',      'BEIDOU'),
    ('GALILEO',     'GALILEO'),
    ('GLONASS',     'GLONASS'),
    ('ORBCOMM',     'ORBCOMM'),
    ('SPIRE',       'SPIRE'),
    ('PLANET',      'FLOCK'),
    ('SKYSAT',      'SKYSAT'),
]

def get_constellation(name):
    name_upper = str(name).upper()
    for label, prefix in CONSTELLATIONS:
        if name_upper.startswith(prefix):
            return label
    return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_constellation)

# ── KPIs ───────────────────────────────────────────────────────────────────────
total_sats      = len(df)
leo_count       = (df['ORBIT_CLASS'] == 'LEO').sum()
leo_share       = leo_count / total_sats * 100
starlink_count  = (df['CONSTELLATION'] == 'STARLINK').sum()
median_incl     = df['INCLINATION'].median()
post2020_count  = (df['LAUNCH_YEAR'] >= 2020).sum()

print(f"Total: {total_sats}, LEO: {leo_count} ({leo_share:.1f}%), Starlink: {starlink_count}")
print(f"Median inclination: {median_incl:.1f}°, Post-2020: {post2020_count}")

# ── Orbit regime breakdown ─────────────────────────────────────────────────────
orbit_counts = df['ORBIT_CLASS'].value_counts().reset_index()
orbit_counts.columns = ['Regime', 'Count']
orbit_counts['Share (%)'] = (orbit_counts['Count'] / total_sats * 100).round(1)

# ── Constellation breakdown ────────────────────────────────────────────────────
const_counts = df['CONSTELLATION'].value_counts().reset_index()
const_counts.columns = ['Constellation', 'Count']
const_counts['Share (%)'] = (const_counts['Count'] / total_sats * 100).round(1)

# ── Launch year trends ─────────────────────────────────────────────────────────
launch_by_year = df.groupby('LAUNCH_YEAR').size().reset_index(name='Count')
launch_by_year = launch_by_year[launch_by_year['LAUNCH_YEAR'] >= 1960].sort_values('LAUNCH_YEAR')
launch_by_year['Cumulative'] = launch_by_year['Count'].cumsum()

# ── Inclination distribution buckets ──────────────────────────────────────────
incl_bins  = [0, 10, 30, 60, 80, 90, 100, 180]
incl_labels = ['0–10°', '10–30°', '30–60°', '60–80°', '80–90°', '90–100°', '100–180°']
df['INCL_BIN'] = pd.cut(df['INCLINATION'], bins=incl_bins, labels=incl_labels, right=False)
incl_dist = df['INCL_BIN'].value_counts().sort_index().reset_index()
incl_dist.columns = ['Range', 'Count']

# ── Generate SVG charts ────────────────────────────────────────────────────────
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch

PALETTE = {
    'primary':   '#1a3a5c',
    'accent1':   '#2196F3',
    'accent2':   '#FF6B35',
    'accent3':   '#4CAF50',
    'accent4':   '#9C27B0',
    'accent5':   '#FF9800',
    'bg':        '#F8FAFD',
    'text':      '#1a2533',
    'grid':      '#e0e8f0',
    'leo':       '#2196F3',
    'meo':       '#4CAF50',
    'geo':       '#FF6B35',
    'heo':       '#9C27B0',
}

ORBIT_COLORS = {'LEO': PALETTE['leo'], 'MEO': PALETTE['meo'],
                'GEO': PALETTE['geo'], 'HEO': PALETTE['heo'], 'Unknown': '#aaa'}

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight',
                facecolor=fig.get_facecolor())
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

def style_ax(ax, title='', xlabel='', ylabel=''):
    ax.set_facecolor(PALETTE['bg'])
    ax.spines[['top','right']].set_visible(False)
    ax.spines[['left','bottom']].set_color(PALETTE['grid'])
    ax.tick_params(colors=PALETTE['text'], labelsize=9)
    ax.xaxis.label.set_color(PALETTE['text'])
