    if xlabel: ax.set_xlabel(xlabel, fontsize=9)
    if ylabel: ax.set_ylabel(ylabel, fontsize=9)

# ── Chart 1: Launch trend (bar + cumulative line) ─────────────────────────────
fig, ax1 = plt.subplots(figsize=(12, 5))
fig.patch.set_facecolor(PALETTE['bg'])

years = launch_by_year['LAUNCH_YEAR'].values
counts = launch_by_year['Count'].values
cumul  = launch_by_year['Cumulative'].values

colors = [PALETTE['accent2'] if y >= 2020 else PALETTE['accent1'] for y in years]
bars = ax1.bar(years, counts, color=colors, alpha=0.85, zorder=3, width=0.7)

ax2 = ax1.twinx()
ax2.plot(years, cumul, color=PALETTE['primary'], linewidth=2.5, zorder=4, marker='o',
         markersize=3, label='Cumulative')
ax2.set_facecolor(PALETTE['bg'])
ax2.spines[['top']].set_visible(False)
ax2.spines[['right']].set_color(PALETTE['grid'])
ax2.tick_params(colors=PALETTE['text'], labelsize=9)
ax2.set_ylabel('Cumulative Active Satellites', fontsize=9, color=PALETTE['primary'])
ax2.yaxis.label.set_color(PALETTE['primary'])

style_ax(ax1, title='Active Satellites by Launch Year',
         xlabel='Launch Year', ylabel='Satellites Launched (still active)')

# Annotation for 2020+
post2020_mask = years >= 2020
if post2020_mask.any():
