    font-weight: 700;
    color: var(--primary);
    letter-spacing: -0.5px;
  }}
  .kpi-sub {{
    font-size: 11px;
    color: var(--muted);
    margin-top: 4px;
  }}

  /* ── Section ── */
  .section {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 32px;
    margin-bottom: 28px;
    box-shadow: var(--shadow);
  }}
  .section-header {{
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--border);
  }}
  .section-badge {{
    background: var(--primary);
    color: white;
    border-radius: 6px;
    padding: 4px 10px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
  }}
  .section h2 {{
    font-size: 18px;
    font-weight: 700;
    color: var(--primary);
  }}
  .section p {{
    color: var(--muted);
    margin-bottom: 16px;
    font-size: 13.5px;
  }}

  /* ── Charts ── */
  .chart-container {{ margin: 20px 0; text-align: center; }}
  .chart-container img {{ max-width: 100%; border-radius: 8px; }}
  .chart-grid-2 {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}

  /* ── Tables ── */
  .table-wrap {{ overflow-x: auto; margin: 16px 0; }}
  table.data-table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }}
  table.data-table thead tr {{
    background: var(--primary);
    color: white;
  }}
  table.data-table th {{
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 12px;
    letter-spacing: 0.3px;
  }}
  table.data-table td {{
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }}
  table.data-table tbody tr:nth-child(even) {{ background: #f4f7fb; }}
  table.data-table tbody tr:hover {{ background: #e8f0fa; }}

  /* ── Insight boxes ── */
  .insight {{
    background: linear-gradient(135deg, #e8f4ff 0%, #f0f8ff 100%);
    border-left: 4px solid var(--accent1);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    margin: 16px 0;
    font-size: 13.5px;
  }}
  .insight.warning {{
    background: linear-gradient(135deg, #fff3e0 0%, #fff8f0 100%);
    border-left-color: var(--accent2);
  }}
  .insight.success {{
    background: linear-gradient(135deg, #e8f5e9 0%, #f1f9f1 100%);
    border-left-color: var(--accent3);
  }}
  .insight strong {{ color: var(--primary); }}

  /* ── Orbit threshold note ── */
  .threshold-box {{
    background: #f0f4f8;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 18px;
    font-size: 12.5px;
    color: var(--muted);
    margin-bottom: 20px;
  }}
  .threshold-box strong {{ color: var(--primary); }}

  /* ── Two-column stat rows ── */
  .stat-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin: 16px 0;
  }}
  .stat-item {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 12px 14px;
    text-align: center;
  }}
  .stat-item .val {{ font-size: 20px; font-weight: 700; color: var(--primary); }}
  .stat-item .lbl {{ font-size: 11px; color: var(--muted); margin-top: 2px; }}

  /* ── Footer ── */
  .report-footer {{
    text-align: center;
    padding: 32px 60px;
    color: var(--muted);
    font-size: 12px;
    border-top: 1px solid var(--border);
    margin-top: 16px;
  }}

  /* ── Callout ── */
  .starlink-callout {{
    background: linear-gradient(135deg, #fff3e0, #ffe9d0);
    border: 1px solid #ffcc80;
    border-radius: 10px;
    padding: 20px 24px;
    margin: 20px 0;
  }}
  .starlink-callout h3 {{
    color: #bf360c;
    font-size: 15px;
    margin-bottom: 8px;
  }}
  .starlink-callout p {{ color: #5d4037; font-size: 13px; margin: 0; }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .chart-grid-2 {{ grid-template-columns: 1fr; }}
    .stat-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .container {{ padding: 24px 20px; }}
    .report-header {{ padding: 32px 20px; }}
  }}
</style>
</head>
<body>

<!-- ══════════ HEADER ══════════ -->
<header class="report-header">
  <div class="tag">Orbital Intelligence Report</div>
  <h1>Active Satellites in Earth Orbit — 2026 Catalog Analysis</h1>
  <div class="subtitle">
    A comprehensive data-driven assessment of the 14,875 active satellites currently orbiting Earth,
    based on CelesTrak / NORAD TLE catalog data.
  </div>
  <div class="header-meta">
    <span>Data Source: CelesTrak / NORAD TLE Catalog</span>
    <span>EPOCH Range: {epoch_min[:10]} – {epoch_max[:10]}</span>
    <span>Report Date: April 2026</span>
    <span>Audience: Space-Industry Analysts & Policy Advisors</span>
  </div>
</header>

<!-- ══════════ BODY ══════════ -->
<div class="container">

<!-- ──── SECTION 0: Executive KPIs ──── -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Total Active Satellites</div>
    <div class="kpi-value">{total_sats:,}</div>
    <div class="kpi-sub">All orbital regimes combined</div>
  </div>
  <div class="kpi-card accent2">
    <div class="kpi-label">LEO Share</div>
    <div class="kpi-value">{leo_share:.1f}%</div>
    <div class="kpi-sub">{leo_count:,} satellites — MEAN_MOTION &gt; 11.25 rev/day</div>
  </div>
  <div class="kpi-card accent3">
    <div class="kpi-label">Starlink Fleet Size</div>
    <div class="kpi-value">{starlink_count:,}</div>
    <div class="kpi-sub">{starlink_share:.1f}% of all active satellites</div>
  </div>
  <div class="kpi-card accent4">
    <div class="kpi-label">Median Inclination</div>
    <div class="kpi-value">{median_incl:.1f}°</div>
    <div class="kpi-sub">Dominated by Starlink 53° shells</div>
  </div>
  <div class="kpi-card accent5">
    <div class="kpi-label">Launched Since 2020</div>
    <div class="kpi-value">{post2020_count:,}</div>
    <div class="kpi-sub">{post2020_count/total_sats*100:.1f}% of active fleet</div>
  </div>
</div>

<!-- ──── SECTION 1: Catalog Overview ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">01</span>
    <h2>Catalog Overview &amp; Key Figures</h2>
  </div>
  <p>
    The catalog captures <strong>{total_sats:,} active satellites</strong> currently in Earth orbit,
    with TLE element sets generated between <strong>{epoch_min[:10]}</strong> and <strong>{epoch_max[:10]}</strong>.
    All orbital data is sourced from NORAD via the CelesTrak platform, representing the most
    comprehensive public record of the operational satellite population.
  </p>

  <div class="stat-grid">
    <div class="stat-item">
      <div class="val">{total_sats:,}</div>
      <div class="lbl">Total Active Satellites</div>
    </div>
    <div class="stat-item">
      <div class="val">{median_mm:.2f}</div>
      <div class="lbl">Median Mean Motion (rev/day)</div>
    </div>
    <div class="stat-item">
      <div class="val">{mean_ecc:.4f}</div>
      <div class="lbl">Mean Eccentricity</div>
    </div>
    <div class="stat-item">
      <div class="val">{pct_circular:.1f}%</div>
      <div class="lbl">Near-Circular (e &lt; 0.01)</div>
    </div>
    <div class="stat-item">
      <div class="val">{median_incl:.1f}°</div>
      <div class="lbl">Median Inclination</div>
    </div>
    <div class="stat-item">
      <div class="val">{post2020_count:,}</div>
      <div class="lbl">Launched 2020–2026</div>
    </div>
    <div class="stat-item">
      <div class="val">{starlink_count:,}</div>
      <div class="lbl">Starlink Satellites</div>
    </div>
    <div class="stat-item">
      <div class="val">{non_starlink:,}</div>
      <div class="lbl">Non-Starlink Satellites</div>
    </div>
  </div>

  <div class="insight">
    <strong>Data freshness:</strong> The catalog's EPOCH field reflects orbital element regeneration
    dates clustered in early 2026, confirming this is a near-real-time snapshot of the active fleet.
    The 17-column TLE-derived schema enables multi-dimensional classification by orbit regime,
    operator, launch cohort, and orbital mechanics.
  </div>
</div>

<!-- ──── SECTION 2: Orbital Regime Classification ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">02</span>
    <h2>Orbital Regime Classification</h2>
  </div>

  <div class="threshold-box">
    <strong>Classification thresholds (MEAN_MOTION-based):</strong>
    &nbsp; LEO: MEAN_MOTION &gt; 11.25 rev/day (~altitude &lt; 2,000 km) &nbsp;|&nbsp;
    MEO: 2.0 – 11.25 rev/day &nbsp;|&nbsp;
    GEO: 0.9 – 1.1 rev/day (circular) &nbsp;|&nbsp;
    HEO: ECCENTRICITY &gt; 0.25 (regardless of mean motion)
  </div>

  <div class="chart-grid-2">
    <div class="chart-container">
      <img src="data:image/png;base64,{chart_orbit}" alt="Orbital regime donut chart">
    </div>
    <div class="table-wrap">
      {orbit_table_html}

      <div class="insight" style="margin-top:16px">
        <strong>LEO dominance is absolute.</strong> {leo_share:.1f}% of all active satellites operate
        in Low Earth Orbit — a direct consequence of Starlink's 53°/70°/97° shells, all at altitudes
        between 540–570 km. MEO hosts navigation constellations (GPS, GLONASS, Galileo, BeiDou).
        GEO remains the preferred regime for broadcast and weather satellites despite its smaller count.
      </div>
    </div>
  </div>

  <div class="insight warning">
    <strong>Orbital congestion risk:</strong> With {leo_count:,} active LEO satellites — and
    thousands more planned — the International Telecommunication Union (ITU) coordination
    processes and FCC licensing frameworks face unprecedented demand for spectrum and
    orbital slot allocations in LEO shells between 400–600 km.
  </div>
</div>

<!-- ──── SECTION 3: Constellation Breakdown ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">03</span>
    <h2>Major Constellation &amp; Operator Breakdown</h2>
  </div>

  <div class="starlink-callout">
    <h3>⚡ Starlink's Statistical Dominance</h3>
    <p>
      SpaceX's Starlink constellation accounts for <strong>{starlink_count:,} satellites
      ({starlink_share:.1f}% of the global active fleet)</strong>. This single operator
      skews every aggregate metric: the global median inclination reflects Starlink's 53°
      shells, LEO's share is inflated by Starlink's density, and any unfiltered
      inclination or altitude histogram is effectively a Starlink histogram.
      Policy analysts must segment Starlink from the broader population to obtain
      meaningful baseline statistics for the rest of the industry.
    </p>
  </div>

  <div class="chart-container">
    <img src="data:image/png;base64,{chart_const}" alt="Constellation breakdown">
  </div>

  <div class="table-wrap">
    {const_table_html}
  </div>

  <div class="insight success">
    <strong>The non-Starlink fleet:</strong> Excluding Starlink, <strong>{non_starlink:,}
    satellites</strong> represent the combined output of all other operators worldwide.
    OneWeb (a distant second) and the four GNSS constellations (GPS, GLONASS, BeiDou, Galileo)
    together represent a fraction of Starlink's scale, underscoring the degree to which
    commercial broadband mega-constellations have reshaped orbital demographics.
  </div>
</div>

<!-- ──── SECTION 4: Launch Year Trends ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">04</span>
    <h2>Launch Year Trends &amp; Growth Acceleration</h2>
  </div>

  <p>
    Launch year is derived from the first four characters of the <code>OBJECT_ID</code>
    international designator (format: <code>YYYY-NNNXXX</code>). The chart below shows
    the count of <em>currently active</em> satellites by their launch year — highlighting
    how the post-2020 era marks a structural break in deployment rates.
  </p>

  <div class="chart-container">
    <img src="data:image/png;base64,{chart_launch}" alt="Launch year trend chart">
  </div>

  <div class="stat-grid">
    <div class="stat-item">
      <div class="val">{post2020_count:,}</div>
      <div class="lbl">Active sats launched 2020–2026</div>
    </div>
    <div class="stat-item">
      <div class="val">{post2020_count/total_sats*100:.1f}%</div>
      <div class="lbl">Share of total active fleet</div>
    </div>
    <div class="stat-item">
      <div class="val">{total_sats - post2020_count:,}</div>
      <div class="lbl">Active sats launched before 2020</div>
    </div>
    <div class="stat-item">
      <div class="val">{(total_sats - post2020_count)/total_sats*100:.1f}%</div>
      <div class="lbl">Pre-2020 share of fleet</div>
    </div>
  </div>

  <div class="insight warning">
    <strong>The post-2020 acceleration is the defining trend.</strong>
    {post2020_count/total_sats*100:.1f}% of today's entire active fleet was launched
    in just the last ~6 years, reflecting Starlink's phased constellation build-out
    and the broader commercialization of launch services (Falcon 9, Rocket Lab, ISRO PSLV).
    The cumulative growth curve has gone near-vertical — a trend that shows no sign of
    plateauing given announced expansion plans from SpaceX, Amazon Kuiper, and others.
  </div>

  <div class="table-wrap">
    <p style="font-size:12px; color:var(--muted); margin-bottom:6px;">Most recent 15 launch years (active satellites only):</p>
    {launch_table_html}
  </div>
</div>

<!-- ──── SECTION 5: Orbital Parameter Deep Dive ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">05</span>
    <h2>Orbital Parameter Deep Dive</h2>
  </div>

  <p>
    The three core TLE orbital parameters — inclination, eccentricity, and mean motion —
    collectively define the shape, tilt, and altitude of each satellite's orbit.
    Their distributions reveal strong clustering around specific commercial and
    government-mandated orbital shells.
  </p>

  <h3 style="font-size:15px; margin-bottom:10px; color:var(--primary);">Inclination Distribution</h3>
  <div class="chart-container">
    <img src="data:image/png;base64,{chart_incl}" alt="Inclination distribution">
  </div>
  <div class="table-wrap">
    {incl_table_html}
  </div>
  <div class="insight">
    <strong>Near-polar orbits dominate LEO:</strong> The 80–100° inclination band is the most
    populated, driven by sun-synchronous and polar Earth-observation satellites (Planet Labs FLOCK,
    Spire, Skysat) as well as Starlink's high-inclination shells. The 50–60° cluster reflects
    Starlink's primary 53° deployment shell. Near-equatorial satellites (0–10°) are largely
    GEO-inclined birds.
  </div>

  <h3 style="font-size:15px; margin: 24px 0 10px; color:var(--primary);">Mean Motion Distribution</h3>
  <div class="chart-container">
    <img src="data:image/png;base64,{chart_mm}" alt="Mean motion distribution">
  </div>
  <div class="insight">
    <strong>Bimodal structure:</strong> The mean motion histogram shows an overwhelming spike
    at ~15 rev/day (LEO Starlink shells at ~540–570 km), a secondary cluster near 14 rev/day
    (other LEO constellations), and a small GEO peak at ~1.0 rev/day. MEO is a thin middle band.
    The 11.25 rev/day LEO threshold clearly separates the two dominant populations.
  </div>

  <h3 style="font-size:15px; margin: 24px 0 10px; color:var(--primary);">Eccentricity Distribution</h3>
  <div class="chart-container">
    <img src="data:image/png;base64,{chart_ecc}" alt="Eccentricity distribution">
  </div>
  <div class="insight success">
    <strong>Near-circular orbits are the overwhelming norm:</strong> {pct_circular:.1f}% of
    active satellites have eccentricity below 0.01, consistent with operational communications
    and Earth-observation constellations that maintain circular orbits for consistent ground
    coverage geometry. Highly eccentric orbits (e &gt; 0.25 — the HEO classification threshold)
    represent a small but specialized population including Molniya and other elliptical
    communication orbits serving high-latitude regions.
  </div>
</div>

<!-- ──── SECTION 6: Conclusions ──── -->
<div class="section">
  <div class="section-header">
    <span class="section-badge">06</span>
    <h2>Key Takeaways &amp; Policy Outlook</h2>
  </div>

  <div style="display:grid; grid-template-columns:1fr 1fr; gap:18px; margin-bottom:20px;">
    <div class="insight">
      <strong>1. LEO is critically crowded.</strong><br>
      {leo_share:.1f}% of all active satellites — {leo_count:,} spacecraft — operate in Low Earth Orbit.
      At the current trajectory, conjunctions, frequency interference, and debris risk will
      intensify substantially before orbital capacity limits are formally defined or regulated.
    </div>
    <div class="insight warning">
      <strong>2. One operator defines the landscape.</strong><br>
      Starlink ({starlink_count:,} satellites, {starlink_share:.1f}% share) is not just the
      largest constellation — it is the statistical majority of the entire active fleet.
      Any aggregate metric — inclination, altitude, mean motion — is primarily a Starlink metric.
      Regulatory frameworks must explicitly segment mega-constellation data.
    </div>
    <div class="insight success">
      <strong>3. The acceleration is structural, not cyclical.</strong><br>
      {post2020_count/total_sats*100:.1f}% of today's active fleet was launched in the past
      six years. This is driven by launch cost reductions, rideshare programs, and commercial
      broadband demand — forces that will persist. Spectrum allocation and orbital slot
      coordination must be forward-looking, not reactive.
    </div>
    <div class="insight">
      <strong>4. Inclination clustering creates interference hotspots.</strong><br>
      The concentration of satellites in 53° and 97° inclination shells creates predictable
      RF coordination challenges. ITU coordination zones and national licensing authorities
      should prioritize these shells for pre-coordination agreements and
      automated spectrum monitoring.
    </div>
  </div>

  <div class="insight warning">
    <strong>5. Debris sustainability.</strong>
    With {leo_count:,} active LEO satellites and thousands more planned by Starlink Gen2,
    Amazon Kuiper, and other entrants, deorbit compliance (IADC's 5-year / FCC's 5-year
    post-mission disposal rule) becomes a critical policy lever. A small non-compliance
    rate at this scale can meaningfully raise background debris flux in critical orbital shells.
  </div>

  <div style="margin-top:20px; padding:20px; background:var(--bg); border-radius:8px; border:1px solid var(--border);">
    <p style="font-size:13px; color:var(--muted); margin:0;">
      <strong style="color:var(--primary)">Data integrity note:</strong>
      All statistics in this report are computed directly from the CelesTrak/NORAD TLE catalog
      ({total_sats:,} rows). No values have been interpolated, modeled, or sourced from
      secondary literature. Orbit classifications use MEAN_MOTION thresholds as documented
      in the Catalog Overview section.
    </p>
  </div>
</div>

</div><!-- /container -->

<!-- ══════════ FOOTER ══════════ -->
<footer class="report-footer">
  <p><strong>Active Satellites in Earth Orbit — 2026 Catalog Analysis</strong></p>
  <p style="margin-top:6px">
    Data: CelesTrak / NORAD TLE Catalog &nbsp;|&nbsp;
    Analysis: Python / pandas / matplotlib &nbsp;|&nbsp;
    Generated: April 2026
  </p>
  <p style="margin-top:4px; color:#aaa;">
    All figures derived directly from data.csv — no fabricated or estimated values.
  </p>
</footer>

</body>
</html>"""

